import java.util.ArrayList;
//Todos los extends e interfaces
public class IntegracionFinanciera extends Integracion implements Consultable, Cobrable, Reintegrable, Auditable {
    protected float saldo;
    private String tipoFinanciero;
    private ArrayList<Evento> eventos;


    // Constructor vacio

    public IntegracionFinanciera() {
        super();
        saldo = 0;
        tipoFinanciero = "";
        eventos = new ArrayList<Evento>();
    }


    // Constructor lleno
    public IntegracionFinanciera(String id, String nombre, int latencia, boolean listo, String configuracion, String tipoFinanciero) {
		//trae lo que ya tenía
        super(id, nombre, latencia, listo, configuracion);
        saldo = 0;
        this.tipoFinanciero = tipoFinanciero;
        eventos = new ArrayList<Evento>();
    }


    // Getter Saldo. Solo el getter, pues lo demás lo cambiamos con cobrar uy reintegrar
    public float getSaldo() {
        return saldo;
    }

	//Tipo
    public void setTipoFinanciero(String newTipo) {
        tipoFinanciero = newTipo;
    }

    public String getTipoFinanciero() {
        return tipoFinanciero;
    }


    // Consultar estado (lo que ya estaba)

    @Override
    public String consultarEstado() {

        if (listo) {
            return "Conectado";
        }
        else {
            return "Desconectado";
        }
    }


    // Implementa y cambia el metodo de cobrar

    @Override
    public boolean cobrar(float monto) {

        if (!listo) {

            registrarEvento(new Evento("La integracion no esta disponible", "Cobro", false
            ));
            return false;
        }

//El monto es un numero, i.e., no es nan (1.8e^308, balatro referencia) ni inifnito
        if (monto <= 0 || Float.isNaN(monto) || Float.isInfinite(monto)) {
            registrarEvento(new Evento(
                "Monto de cobro invalido: Q" + monto,
                "Cobro", false
            ));
            return false;
        }

        // Aumenta el saldo con el monto cobrado.
        saldo += monto;

        registrarEvento(new Evento("Cobro realizado por Q" + monto, "Cobro", true));
        return true;
    }


    // Reintegrable
    @Override
    public boolean reintegrar(float monto) {

        if (!listo) {
            registrarEvento(new Evento("La integracion no esta disponible","Reintegro", false));

            return false;
        }

		//otra vez, no quiero naneinf
        if (monto <= 0 || Float.isNaN(monto) || Float.isInfinite(monto)) {
            registrarEvento(new Evento("Monto de reintegro invalido: Q" + monto,"Reintegro", false));
            return false;
        }

        // Solo regreso lo cobrado
        if (monto > saldo) {
            registrarEvento(new Evento("Saldo insuficiente para reintegrar Q" + monto, "Reintegro", false));
            return false;
        }
        saldo -= monto;

        registrarEvento(new Evento("Reintegro realizado por Q" + monto,"Reintegro", true));
        return true;
    }


    // Registrar evento

    @Override
    public void registrarEvento(Evento evento) {
        if (evento != null) {
            eventos.add(evento);
        }
    }


    // Mostrar Eventos
    @Override
    public ArrayList<Evento> consultarHistorialEventos() {

        return new ArrayList<Evento>(eventos);
    }


    // ToString

    @Override
    public String toString() {

        return super.toString()
            + "\nTipo financiero: " + tipoFinanciero
            + "\nSaldo disponible: Q" + saldo;
    }
}
